// src/uhuu/i18n/i18n-core.js
// Pure, DOM-free translation core for the editor shell. The React wiring is in
// locale-context.tsx and the catalogs in ./locales. The catalog conventions are the Embed SPAs'
// (uhuu-embed/docs/ui-translations.md): nested keys, `{{placeholders}}`, and i18next plural
// suffixes (`_one`, `_many`, `_other`) selected through Intl.PluralRules, so one translator can
// work on both.

export const DEFAULT_SHELL_LOCALE = 'en';

/** Query parameters that pick the shell language on a standalone or dev page (`?lang=fr`). */
export const SHELL_LOCALE_QUERY_PARAMS = ['lang', 'locale'];

/** `de-CH`, `fr_FR`, ` IT ` → `de`, `fr`, `it`; anything that is not a language tag → null. */
export function normalizeLanguageTag(value) {
  if (typeof value !== 'string') return null;
  const base = value.trim().toLowerCase().split(/[-_]/)[0];
  return /^[a-z]{2,3}$/.test(base) ? base : null;
}

/**
 * First candidate that is a language tag. With `supported`, the first candidate whose language
 * has a catalog (for preference lists such as `navigator.languages`). Null when none matches.
 */
export function pickLanguage(candidates, supported) {
  for (const candidate of candidates ?? []) {
    const language = normalizeLanguageTag(candidate);
    if (!language) continue;
    if (!supported || supported.includes(language)) return language;
  }
  return null;
}

/**
 * The shell language, from the first source that names one: the explicit `locale`, the host's
 * declaration (uhuu-app's resolved UI language), `?lang=` / `?locale=` on the page URL,
 * `<html lang>`, the browser's preference list (first language with a catalog), then `en`.
 * Explicit sources may name a language without a catalog; its words then fall back to English
 * while `locale` still reports it, so a template's own labels can follow it.
 */
export function resolveShellLocale(sources, supported) {
  const params = new URLSearchParams(sources?.search ?? '');
  return (
    pickLanguage([
      sources?.locale,
      sources?.host,
      ...SHELL_LOCALE_QUERY_PARAMS.map((name) => params.get(name)),
      sources?.documentLang,
    ]) ??
    pickLanguage(sources?.navigatorLanguages ?? [], supported) ??
    DEFAULT_SHELL_LOCALE
  );
}

/**
 * The language uhuu-app resolved for the user reaches a template frame in the host handshake
 * (`uhuuData.locale` in the `shaked` snapshot), which the SDK re-emits as its `loaded` event.
 * Reports the language it names, if any; returns the unsubscribe. No-op without the SDK.
 */
export function subscribeHostLocale(uhuu, onLocale) {
  if (typeof uhuu?.listen !== 'function') return () => {};
  const off = uhuu.listen('loaded', (data) => {
    const language = normalizeLanguageTag(data?.locale);
    if (language) onLocale(language);
  });
  return typeof off === 'function' ? off : () => {};
}

function isCatalogNode(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function deepMergeCatalog(base, override) {
  if (!isCatalogNode(override)) return base;
  const merged = { ...(isCatalogNode(base) ? base : {}) };
  for (const [key, value] of Object.entries(override)) {
    if (value === undefined || value === null) continue;
    merged[key] = isCatalogNode(value) && isCatalogNode(merged[key]) ? deepMergeCatalog(merged[key], value) : value;
  }
  return merged;
}

/**
 * Built-in catalogs with a template's `translations` merged over them, per language. A language
 * the built-ins lack is added as given; its missing keys fall back to English at lookup time.
 */
export function mergeTranslations(builtIn, overrides) {
  const merged = { ...(builtIn ?? {}) };
  for (const [tag, catalog] of Object.entries(overrides ?? {})) {
    const language = normalizeLanguageTag(tag);
    if (!language || !isCatalogNode(catalog)) continue;
    merged[language] = deepMergeCatalog(merged[language], catalog);
  }
  return merged;
}

/**
 * A label that is one string, or one string per language (`{ en: 'Cover', de: 'Titelseite' }`):
 * the active language, then English, then the first language given. Undefined for no label.
 */
export function localizeText(value, locale, fallbackLocale = DEFAULT_SHELL_LOCALE) {
  if (value === null || value === undefined) return undefined;
  if (typeof value === 'string') return value;
  if (!isCatalogNode(value)) return String(value);
  const language = normalizeLanguageTag(locale);
  const candidates = [locale, language, fallbackLocale].filter(Boolean);
  for (const tag of candidates) {
    if (typeof value[tag] === 'string') return value[tag];
  }
  const first = Object.values(value).find((entry) => typeof entry === 'string');
  return typeof first === 'string' ? first : undefined;
}

/**
 * Whether a label stored in a document's page-editor state is the template's own label rather than
 * a user rename. PageEditor persists every item with its label, so documents saved before a
 * template made its labels per-language carry the English string. A rename is always a string; a
 * stored per-language object, a missing label, or a string equal to one of the template label's
 * values is the template's label, which restore replaces with the current config label.
 */
export function isTemplateLabel(stored, templateLabel) {
  if (stored === null || stored === undefined) return true;
  if (typeof stored !== 'string') return true;
  if (templateLabel === null || templateLabel === undefined) return false;
  if (typeof templateLabel === 'string') return stored === templateLabel;
  return Object.values(templateLabel).includes(stored);
}

const pluralRules = new Map();

function pluralCategory(locale, count) {
  if (!pluralRules.has(locale)) {
    let rules = null;
    try {
      rules = new Intl.PluralRules(locale);
    } catch {
      rules = null;
    }
    pluralRules.set(locale, rules);
  }
  const rules = pluralRules.get(locale);
  if (rules) return rules.select(count);
  return count === 1 ? 'one' : 'other';
}

function lookup(catalog, key) {
  let node = catalog;
  for (const part of key.split('.')) {
    if (!isCatalogNode(node)) return undefined;
    node = node[part];
  }
  return typeof node === 'string' ? node : undefined;
}

function interpolate(text, params) {
  if (!params) return text;
  return text.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (match, name) => {
    const value = params[name];
    return value === undefined || value === null ? match : String(value);
  });
}

/**
 * `t(key, params)` over merged catalogs: the active language first, then English. With a numeric
 * `params.count`, `key_<plural category>` is tried before `key_other` and `key`, within each
 * language in turn (a language's `_other` beats English's `_one`). A key no catalog has is
 * returned as written, so a missing word is visible instead of blank.
 */
export function createTranslator({ locale, catalogs, fallbackLocale = DEFAULT_SHELL_LOCALE }) {
  const language = normalizeLanguageTag(locale) ?? fallbackLocale;
  const chain = [...new Set([language, fallbackLocale])]
    .map((tag) => catalogs?.[tag])
    .filter(isCatalogNode);

  return function t(key, params) {
    const count = typeof params?.count === 'number' ? params.count : null;
    const variants = count === null ? [key] : [`${key}_${pluralCategory(language, count)}`, `${key}_other`, key];
    for (const catalog of chain) {
      for (const variant of variants) {
        const text = lookup(catalog, variant);
        if (text !== undefined) return interpolate(text, params);
      }
    }
    return key;
  };
}

/** `{ a: { b: 'x' } }` → Map { 'a.b' → 'x' }. */
export function flattenCatalog(catalog, prefix = '', out = new Map()) {
  for (const [key, value] of Object.entries(catalog ?? {})) {
    const path = prefix ? `${prefix}.${key}` : key;
    if (isCatalogNode(value)) flattenCatalog(value, path, out);
    else out.set(path, value);
  }
  return out;
}

const PLURAL_SUFFIX = /_(zero|one|two|few|many|other)$/;

function placeholders(text) {
  const found = text.match(/\{\{\s*[^}]+?\s*\}\}/g) ?? [];
  return [...new Set(found.map((p) => p.replace(/\s+/g, '')))].sort().join(' ');
}

function groupByBase(entries) {
  const groups = new Map();
  for (const [key, value] of entries) {
    const base = key.replace(PLURAL_SUFFIX, '');
    if (!groups.has(base)) groups.set(base, new Map());
    groups.get(base).set(key, value);
  }
  return groups;
}

/**
 * Compares every catalog with the source (`en`): the same keys, every plural form the language's
 * Intl.PluralRules selects, non-empty strings, and the source's `{{placeholders}}`. The same
 * rules as the Embed SPAs' parity check, so a catalog that passes here passes there.
 */
export function checkCatalogParity(catalogs, source = DEFAULT_SHELL_LOCALE) {
  const issues = [];
  const reference = groupByBase(flattenCatalog(catalogs?.[source] ?? {}));

  for (const [locale, catalog] of Object.entries(catalogs ?? {})) {
    if (locale === source) continue;
    const groups = groupByBase(flattenCatalog(catalog));

    for (const [base, referenceGroup] of reference) {
      const group = groups.get(base);
      if (!group) {
        issues.push({ locale, key: base, problem: 'missing' });
        continue;
      }
      const plural = !referenceGroup.has(base);
      if (plural) {
        for (const category of new Intl.PluralRules(locale).resolvedOptions().pluralCategories) {
          if (!group.has(`${base}_${category}`)) issues.push({ locale, key: `${base}_${category}`, problem: 'missing' });
        }
      } else if (!group.has(base)) {
        issues.push({ locale, key: base, problem: 'missing' });
      }

      for (const [key, value] of group) {
        if (typeof value !== 'string') {
          issues.push({ locale, key, problem: 'not-a-string' });
          continue;
        }
        if (!value.trim()) {
          issues.push({ locale, key, problem: 'empty' });
          continue;
        }
        const expected = referenceGroup.get(key) ?? referenceGroup.get(`${base}_other`) ?? referenceGroup.get(base);
        if (typeof expected === 'string' && placeholders(value) !== placeholders(expected)) {
          issues.push({ locale, key, problem: 'placeholders', detail: `expected "${placeholders(expected)}", got "${placeholders(value)}"` });
        }
      }
    }
    for (const base of groups.keys()) {
      if (!reference.has(base)) issues.push({ locale, key: base, problem: 'extra' });
    }
  }
  return issues;
}
