/**
 * Geometry shared by `ImageBleed` / `ImageSpread` and the editor chrome ("…" options
 * menu) that has to sit on top of them.
 *
 * Both components render their image into an absolutely positioned
 * `.uhuu-image-container` whose containing block is the page sheet's padding box — so a
 * trim-relative inset of `n` mm becomes `n + bleed` from the page edge, and an inset of 0
 * means "run off the page edge".
 *
 * The options button cannot live inside that container: for a spread the container is two
 * pages wide, so its top-right corner sits on the *other* page. It also cannot be wrapped
 * in a `relative` element, because that would break the container's page-relative
 * positioning. Instead it is rendered as a sibling inside a zero-cost anchor box that
 * reproduces the container's rect, clamped to the page the image is rendered on.
 */

export interface ImageAnchorInput {
  width?: number
  left?: number
  right?: number
  top?: number
  bottom?: number
  pageWidth?: number
  bleed?: number
  /** Set for spread mode; omit for bleed mode. */
  side?: 'start' | 'end'
}

export interface ImageAnchorInsets {
  top: string
  right: string
}

/**
 * Trim-relative inset → page-relative inset. A positive inset is measured from the trim
 * edge so the bleed margin is added to it; 0 means the image bleeds off the page edge.
 */
export const toPageInset = (value: number | undefined, bleed: number): number =>
  value && value > 0 ? value + bleed : 0

/**
 * Width of the image container, in mm. `pageSpan` is 1 for bleed images and 2 for
 * spreads. Kept here so `ImageBleed`, `ImageSpread` and the anchor can never disagree.
 */
export const resolveImageWidth = (
  { width, left = 0, right = 0 }: Pick<ImageAnchorInput, 'width' | 'left' | 'right'>,
  pageWidth: number,
  bleed: number,
  pageSpan: 1 | 2
): number => {
  if (width) {
    return !left && !right ? width + bleed : width
  }

  let result = pageSpan * pageWidth
  if (!left) result += pageSpan * bleed
  if (!right) result += pageSpan * bleed
  if (left || right) result -= left + right
  return result
}

/**
 * Insets that place the options button at the top-right corner of the part of the image
 * that is visible on this page. `right` is derived from the container's real right edge
 * (left + width) rather than the `right` inset, because the container sets left, width and
 * right together and CSS drops `right` when a box is over-constrained.
 */
export const resolveImageAnchorInsets = (
  props: ImageAnchorInput,
  mode: 'bleed' | 'spread'
): ImageAnchorInsets => {
  const bleed = props.bleed ?? 0
  const pageWidth = props.pageWidth ?? 210
  const pageSpan = mode === 'spread' ? 2 : 1
  const pageBoxWidth = pageWidth + 2 * bleed

  const width = resolveImageWidth(props, pageWidth, bleed, pageSpan)
  const leftInset = toPageInset(props.left, bleed)
  // A spread's `end` half starts a full page to the left of the page it renders on.
  const containerLeft = mode === 'spread' && props.side === 'end' ? -pageWidth + leftInset : leftInset
  const rightInset = pageBoxWidth - (containerLeft + width)

  return {
    top: `${Math.max(0, toPageInset(props.top, bleed))}mm`,
    right: `${Math.max(0, rightInset)}mm`,
  }
}
