/**
 * brandkit.json → CSS custom properties, the one mapping every template shares. The table, the
 * accepted kit shapes and the colour policy are in docs/brand-kit-runtime.md; keep that page and
 * the tables below in step.
 *
 * - A kit published by Brand Kit carries `runtime` (v2): the variables already mapped and converted
 *   at publish, in shadcn/ui's names (`--primary`, `--color-primary`) plus the `--color-kit-*` /
 *   `--font-kit-*` aliases. It is used as is, re-validated, and the chains below are skipped.
 *   Template-bundled kits go through the chains.
 *
 * - Colours land on `--color-kit-<slot>`; each slot reads a chain of tokens and the first
 *   print-safe value wins. `tokens.light.aliases` add `--color-kit-<key>` and win over a slot.
 *   Brand Kit's semantic roles (`tokens.light.semantic`) also land on `--<role>` and `--color-<role>`.
 * - Fonts land on both `--font-<role>` and `--font-kit-<role>`, with the same value.
 * - Print safety: hex, `rgb()`/`rgba()`, `oklch()`/`oklab()` and colour keywords pass, HSL is
 *   converted, anything else is skipped as if absent, so the template's own fallback (`@theme` or
 *   `defaults`) renders.
 *
 * Pure, DOM-free and dependency-free: safe in the renderer, on the server and in Node tests.
 */
import { hasOwn, isPlainObject, textOf } from '../utility/json.js';

/**
 * `--color-kit-<slot>` ← sources, first print-safe value wins. A bare name reads `tokens.<name>`,
 * `s:<name>` reads `tokens.light.semantic.<name>`, `hero:<name>` reads `tokens.light.aliases.hero`.
 * The chains are the go-expose runtime's (the skill's reference), with one deliberate change: an
 * explicit `colorHighlight` / `highlight` token wins over the accent highlight otherwise derives
 * from, and that accent is read like `--color-kit-accent` (legacy `colorAccent` included).
 */
export const COLOR_SLOTS = [
  ['primary', ['primary', 'colorPrimary', 's:primary']],
  ['primary-foreground', ['primaryForeground', 's:primaryForeground']],
  ['secondary', ['secondary', 'colorSecondary', 's:secondary']],
  ['secondary-foreground', ['secondaryForeground', 's:secondaryForeground']],
  ['secondary-soft', ['accent', 'colorAccent', 's:accent', 's:secondary']],
  ['secondary-muted', ['mutedForeground', 'colorMuted', 's:mutedForeground', 's:secondary']],
  ['accent', ['accent', 'colorAccent', 's:accent']],
  ['accent-foreground', ['accentForeground', 's:accentForeground']],
  ['text', ['foreground', 'colorForeground', 's:foreground']],
  ['muted', ['muted', 's:muted']],
  ['muted-foreground', ['mutedForeground', 'colorMuted', 's:mutedForeground', 's:foreground']],
  ['divider', ['border', 'colorBorder', 's:border']],
  ['surface', ['card', 'colorSurface', 's:card', 's:background']],
  ['surface-foreground', ['cardForeground', 's:cardForeground', 's:foreground']],
  ['placeholder', ['input', 's:input', 's:border']],
  ['highlight', ['colorHighlight', 'highlight', 'accent', 'colorAccent', 's:accent', 's:primary']],
  ['hero-from', ['heroFrom', 'hero:from']],
  ['hero-via', ['heroVia', 'hero:via']],
  ['hero-to', ['heroTo', 'hero:to']],
  ['hero-glow', ['heroGlow', 'hero:glow']],
];

/**
 * Font roles. A role's family comes from, in order: the font `assignments['font.<role>']` names
 * in `fonts`; a `fonts` entry keyed by the role (`sans`/`body`, `display`/`heading`, `serif`,
 * `mono`); `tokens.fontFamily<Role>`; `tokens.primitives.typography.font<Role>`.
 */
export const FONT_ROLES = [
  ['sans', { token: 'fontFamilySans', primitive: 'fontSans', keys: ['sans', 'body'], generic: 'sans-serif' }],
  ['serif', { token: 'fontFamilySerif', primitive: 'fontSerif', keys: ['serif'], generic: 'serif' }],
  ['display', { token: 'fontFamilyDisplay', primitive: 'fontDisplay', keys: ['display', 'heading'], generic: 'sans-serif' }],
  ['mono', { token: 'fontFamilyMono', primitive: 'fontMono', keys: ['mono'], generic: 'monospace' }],
];

/**
 * shadcn/ui colour roles, as Brand Kit's runtime and `tokens.light.semantic` name them. A role
 * reads the nested semantic token only: flat tokens in template-bundled kits use some of these
 * words with other meanings (`muted` is grey text there), so they feed the `kit-*` chains instead.
 */
export const ROLE_SLOTS = [
  ['background', 'background'],
  ['foreground', 'foreground'],
  ['card', 'card'],
  ['card-foreground', 'cardForeground'],
  ['popover', 'popover'],
  ['popover-foreground', 'popoverForeground'],
  ['primary', 'primary'],
  ['primary-foreground', 'primaryForeground'],
  ['secondary', 'secondary'],
  ['secondary-foreground', 'secondaryForeground'],
  ['muted', 'muted'],
  ['muted-foreground', 'mutedForeground'],
  ['accent', 'accent'],
  ['accent-foreground', 'accentForeground'],
  ['destructive', 'destructive'],
  ['destructive-foreground', 'destructiveForeground'],
  ['border', 'border'],
  ['input', 'input'],
  ['ring', 'ring'],
];

/** The `brandkit.json.runtime` contract this module reads. */
export const BRAND_KIT_RUNTIME_VERSION = 2;
const ROLE_NAMES = [...ROLE_SLOTS.map(([name]) => name), 'chart-1', 'chart-2', 'chart-3', 'chart-4', 'chart-5'];
// A role as `--<role>` or `--color-<role>`, or a kit alias. Nothing else: a document from anywhere
// must not be able to set `--radius` or `--spacing` on a template.
const RUNTIME_ROLE_NAME = new RegExp(`^--(?:color-)?(?:${ROLE_NAMES.join('|')})$`);
const RUNTIME_COLOR_NAME = /^--color-kit-[A-Za-z0-9_-]+$/;
const RUNTIME_FONT_NAME = /^--font-(?:kit-)?(?:sans|serif|display|mono)$/;

/** The kit's `runtime` block when it is one this module understands, else `undefined`. */
export function brandKitRuntime(brandKit) {
  const runtime = isPlainObject(brandKit) ? brandKit.runtime : undefined;
  return isPlainObject(runtime) && runtime.version === BRAND_KIT_RUNTIME_VERSION && isPlainObject(runtime.light)
    ? runtime
    : undefined;
}

const HEX = /^#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;
const RGB = /^rgba?\(\s*[\d.%\s,/+-]+\)$/i;
// Brand Kit publishes oklch(); Chrome has printed it since 111. Plain components only: no
// relative colour syntax, no nested functions.
const OK_COMPONENT = '(?:[+-]?(?:\\d+\\.?\\d*|\\.\\d+)(?:%|deg)?|none)';
const OKLAB = new RegExp(`^ok(?:lch|lab)\\(\\s*${OK_COMPONENT}\\s+${OK_COMPONENT}\\s+${OK_COMPONENT}(?:\\s*\\/\\s*${OK_COMPONENT})?\\s*\\)$`, 'i');
const KEYWORD = /^[a-z]+$/i;
const CSS_WIDE_KEYWORDS = new Set(['inherit', 'initial', 'unset', 'revert', 'none']);
const NUMBER = '[+-]?(?:\\d+\\.?\\d*|\\.\\d+)';
const HSL_TRIPLET = new RegExp(
  `^(${NUMBER})(deg|turn|rad|grad)?\\s+(${NUMBER})%\\s+(${NUMBER})%(?:\\s*\\/\\s*(${NUMBER})(%)?)?$`,
  'i',
);
const HSL_FUNCTION = new RegExp(
  `^hsla?\\(\\s*(${NUMBER})(deg|turn|rad|grad)?\\s*(?:,\\s*|\\s+)(${NUMBER})%\\s*(?:,\\s*|\\s+)(${NUMBER})%` +
    `\\s*(?:(?:,|\\/)\\s*(${NUMBER})(%)?\\s*)?\\)$`,
  'i',
);
// A value that could close the declaration or the element it is written into.
const UNSAFE_VALUE = /[;{}<>\\\n\r]/;
const ALIAS_KEY = /^[A-Za-z0-9_-]+$/;

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const hex2 = (value) => value.toString(16).padStart(2, '0');

const HUE_UNIT = { deg: 1, turn: 360, rad: 180 / Math.PI, grad: 0.9 };

function hslToCss(hue, unit, saturation, lightness, alpha, alphaIsPercent) {
  const h = (((Number(hue) * HUE_UNIT[(unit || 'deg').toLowerCase()]) % 360) + 360) % 360;
  const s = clamp(Number(saturation) / 100, 0, 1);
  const l = clamp(Number(lightness) / 100, 0, 1);
  // CSS Color 4 `hslToRgb`.
  const a = s * Math.min(l, 1 - l);
  const channel = (n) => {
    const k = (n + h / 30) % 12;
    return Math.round((l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))) * 255);
  };
  const [r, g, b] = [channel(0), channel(8), channel(4)];
  const opacity = alpha === undefined ? 1 : clamp(Number(alpha) / (alphaIsPercent ? 100 : 1), 0, 1);
  if (opacity >= 1) return `#${hex2(r)}${hex2(g)}${hex2(b)}`;
  return `rgba(${r}, ${g}, ${b}, ${Number(opacity.toFixed(3))})`;
}

/**
 * The print-safe spelling of a colour, or `undefined` when there is none. Hex, `rgb()`/`rgba()`,
 * `oklch()`/`oklab()` and colour keywords pass through as written; HSL (a bare `H S% L%` triplet as
 * pre-2.0 brand kits store it, or `hsl()`/`hsla()` in comma or space syntax) is converted to
 * `#rrggbb`, or `rgba()` with alpha.
 */
export function toPrintSafeColor(value) {
  const color = textOf(value);
  if (!color) return undefined;
  if (HEX.test(color) || RGB.test(color) || OKLAB.test(color)) return color;
  if (KEYWORD.test(color)) return CSS_WIDE_KEYWORDS.has(color.toLowerCase()) ? undefined : color;
  const hsl = HSL_TRIPLET.exec(color) ?? HSL_FUNCTION.exec(color);
  if (hsl) return hslToCss(hsl[1], hsl[2], hsl[3], hsl[4], hsl[5], Boolean(hsl[6]));
  return undefined;
}

function readSource(tokens, source) {
  if (source.startsWith('s:')) {
    const semantic = tokens.light?.semantic;
    return isPlainObject(semantic) ? semantic[source.slice(2)] : undefined;
  }
  if (source.startsWith('hero:')) {
    const hero = tokens.light?.aliases?.hero;
    return isPlainObject(hero) ? hero[source.slice(5)] : undefined;
  }
  return tokens[source];
}

/** First source in the chain with a print-safe colour. */
function firstPrintSafe(tokens, sources) {
  for (const source of sources) {
    const color = toPrintSafeColor(readSource(tokens, source));
    if (color !== undefined) return color;
  }
  return undefined;
}

/** Everything after a stack's first family, or `undefined` for a single family. */
const stackTail = (stack) => {
  if (typeof stack !== 'string' || !stack.includes(',')) return undefined;
  return textOf(stack.slice(stack.indexOf(',') + 1));
};

/**
 * A stack (anything with a comma) is used as written. A single family is quoted and given a tail
 * to fall back to, because these documents render to PDF, where a webfont that fails to load
 * otherwise falls back to whatever the renderer picks. Same rule as the platform's
 * `composeFontStack`.
 */
function composeStack(family, tail) {
  if (family.includes(',')) return family;
  const quoted = /^(["']).*\1$/.test(family) ? family : `"${family}"`;
  return tail ? `${quoted}, ${tail}` : quoted;
}

function fontRecord(fonts, id) {
  if (typeof id !== 'string' || !id) return undefined;
  if (Array.isArray(fonts)) return fonts.find((font) => isPlainObject(font) && font.id === id);
  if (!isPlainObject(fonts)) return undefined;
  if (hasOwn(fonts, id) && isPlainObject(fonts[id])) return fonts[id];
  return Object.values(fonts).find((font) => isPlainObject(font) && font.id === id);
}

/** The CSS font stack for one role, or `undefined` when the kit names no family for it. */
export function resolveFontStack(brandKit, role) {
  const spec = FONT_ROLES.find(([name]) => name === role)?.[1];
  if (!spec || !isPlainObject(brandKit)) return undefined;
  const tokens = isPlainObject(brandKit.tokens) ? brandKit.tokens : {};
  const tokenStack = textOf(tokens[spec.token]);
  const primitiveStack = textOf(tokens.primitives?.typography?.[spec.primitive]);

  let record = fontRecord(brandKit.fonts, brandKit.assignments?.[`font.${role}`]);
  if (!textOf(record?.family) && isPlainObject(brandKit.fonts)) {
    record = spec.keys
      .map((key) => (hasOwn(brandKit.fonts, key) ? brandKit.fonts[key] : undefined))
      .find((font) => isPlainObject(font) && textOf(font.family));
  }

  const family = textOf(record?.family);
  if (family) {
    return composeStack(
      family,
      textOf(record.fallback) ?? stackTail(primitiveStack) ?? stackTail(tokenStack) ?? spec.generic,
    );
  }

  const stack = tokenStack ?? primitiveStack;
  return stack ? composeStack(stack, stackTail(primitiveStack) ?? spec.generic) : undefined;
}

/**
 * CSS custom properties for a brand kit, ready to spread onto `style`.
 *
 * @param {object|null|undefined} brandKit  A brandkit.json document.
 * @param {{ defaults?: Record<string, string> }} [options]  `defaults`: custom properties to emit
 *   when the kit provides no value for them (the kit wins). Colour defaults (`--color-*`) follow
 *   the same print policy.
 * @returns {Record<string, string>}
 */
export function brandKitCssVars(brandKit, options = {}) {
  const vars = {};

  if (isPlainObject(options?.defaults)) {
    for (const [name, raw] of Object.entries(options.defaults)) {
      if (!name.startsWith('--')) continue;
      const value = name.startsWith('--color-') ? toPrintSafeColor(raw) : textOf(raw);
      if (value !== undefined && !UNSAFE_VALUE.test(value)) vars[name] = value;
    }
  }

  if (!isPlainObject(brandKit)) return vars;

  // Precomputed at publish: re-validate each entry (the document may come from anywhere) and stop.
  // Unknown names are ignored, so a newer runtime with more variables still applies what it can.
  const runtime = brandKitRuntime(brandKit);
  if (runtime) {
    for (const [name, raw] of Object.entries(runtime.light)) {
      const value = RUNTIME_ROLE_NAME.test(name) || RUNTIME_COLOR_NAME.test(name)
        ? toPrintSafeColor(raw)
        : RUNTIME_FONT_NAME.test(name)
          ? textOf(raw)
          : undefined;
      if (value !== undefined && !UNSAFE_VALUE.test(value)) vars[name] = value;
    }
    return vars;
  }

  const tokens = isPlainObject(brandKit.tokens) ? brandKit.tokens : {};

  const semantic = isPlainObject(tokens.light?.semantic) ? tokens.light.semantic : {};
  for (const [name, key] of ROLE_SLOTS) {
    const value = toPrintSafeColor(semantic[key]);
    if (value === undefined) continue;
    vars[`--${name}`] = value;
    vars[`--color-${name}`] = value;
  }

  for (const [slot, sources] of COLOR_SLOTS) {
    const value = firstPrintSafe(tokens, sources);
    if (value !== undefined) vars[`--color-kit-${slot}`] = value;
  }

  const aliases = tokens.light?.aliases;
  if (isPlainObject(aliases)) {
    const alias = (key, raw) => {
      const value = ALIAS_KEY.test(key) ? toPrintSafeColor(raw) : undefined;
      if (value !== undefined) vars[`--color-kit-${key}`] = value;
    };
    // Groups first, flat keys last, so a flat alias wins whatever the key order in the file.
    // `template` is where the BrandKit app stores template-specific slots, which extracted kits
    // keep flat: both spell `--color-kit-<key>`, so the two kits converge on one name.
    for (const [key, raw] of Object.entries(aliases)) {
      if (key === 'hero' || !isPlainObject(raw)) continue;
      for (const [subKey, subRaw] of Object.entries(raw)) {
        alias(key === 'template' ? subKey : `${key}-${subKey}`, subRaw);
      }
    }
    for (const [key, raw] of Object.entries(aliases)) {
      if (!isPlainObject(raw)) alias(key, raw);
    }
  }

  for (const [role] of FONT_ROLES) {
    const stack = resolveFontStack(brandKit, role);
    if (stack === undefined || UNSAFE_VALUE.test(stack)) continue;
    vars[`--font-${role}`] = stack;
    vars[`--font-kit-${role}`] = stack;
  }

  return vars;
}
