// Hold pagination pending while intrinsic image sizes or web fonts can still change the flow.
// ResizeObserver alone is insufficient: it may not deliver callbacks in a background document.
//
// `root` is the page's hidden measurement copy, which the library owns: images there load eagerly.
// A `loading="lazy"` image (CMS HTML, next/image) never intersects the viewport offscreen, so it
// would never load and pagination would wait forever. The visible sheets keep their attribute.
export function observeFlowAssets(root, { begin, onReady, doc = root.ownerDocument }) {
  const images = new Map();
  const fonts = doc?.fonts;
  let stopped = false;
  let finishFonts = null;

  const watchFonts = () => {
    if (stopped || !fonts || fonts.status !== 'loading' || finishFonts) return;
    finishFonts = begin();
    const ready = () => {
      if (stopped) return;
      onReady();
      finishFonts?.();
      finishFonts = null;
    };
    fonts.ready.then(ready, ready);
  };
  fonts?.addEventListener('loading', watchFonts);
  watchFonts();

  const sync = () => {
    for (const [image, cleanup] of images) {
      if (!root.contains(image) || image.complete) cleanup();
    }
    for (const image of root.querySelectorAll('img')) {
      if (image.loading === 'lazy') image.loading = 'eager';
      if (image.complete || images.has(image)) continue;
      const finish = begin();
      const cleanup = () => {
        image.removeEventListener('load', loaded);
        image.removeEventListener('error', loaded);
        images.delete(image);
        finish();
      };
      const loaded = () => {
        if (!stopped) onReady();
        cleanup();
      };
      images.set(image, cleanup);
      image.addEventListener('load', loaded);
      image.addEventListener('error', loaded);
    }
    // Catch a font load that started before its `loading` event is delivered.
    watchFonts();
  };
  sync();
  return {
    sync,
    disconnect() {
      stopped = true;
      fonts?.removeEventListener('loading', watchFonts);
      finishFonts?.();
      finishFonts = null;
      for (const cleanup of images.values()) cleanup();
    },
  };
}
