import * as React from 'react';
import Pagination from '../../pagination-static/pagination-static';
import Sheet from '../../pagination-static/sheet-static';
import {
  StaticFlowContext,
  type StaticFlowChunk,
  type StaticFlowContextValue,
  type StaticFlowMeasurement,
} from '../../pagination-static/flow-static';
import type { paginationReadiness } from '../../pagination-static/pagination-readiness';
import { isDev } from '../../utility/is-dev';
import type { PageComponent, PageGroup, PageItem, SpreadInfo, StandalonePage } from './page-group-utils';
import type { PageDataBinding } from './data-binding';

const useIsoLayoutEffect = typeof window === 'undefined' ? React.useEffect : React.useLayoutEffect;
const MISSING_REGION_GRACE_MS = 1000;
const warnedMissingRegions = new Set<string>();

interface PageCanvasProps {
  pageId: string;
  templateId?: string;
  componentKey?: string;
  component?: PageComponent;
  payload?: any;
  pagePayload?: any;
  integration?: any;
  page?: StandalonePage;
  parentGroup?: PageItem;
  setup?: { width: number; height: number; [key: string]: any };
  reference?: React.ReactNode;
  overlay?: React.ReactNode | ((args: { pageNo: number; pageId: string }) => React.ReactNode);
  className?: string;
  pageNo?: number;
  totalPages?: number;
  measurementPageNo?: number;
  measurementTotalPages?: number;
  dataBinding?: PageDataBinding;
  flowPageIndex?: number;
  flowChunksByFlowId?: Record<string, StaticFlowChunk[]>;
  measureFlow?: boolean;
  flowMeasurementKey?: string;
  flowMeasurementVersion?: string;
  flowReadiness?: ReturnType<typeof paginationReadiness.createScope>;
  onFlowMeasurement?: (pageKey: string, measurement: StaticFlowMeasurement, owner?: string) => void;
  onFlowRemoval?: (pageKey: string, flowId: string, owner: string) => void;
  renderVisible?: boolean;
  /**
   * `sheet` (default) wraps the page in Pagination + Sheet. `content` returns only the
   * page component (plus reference overlay) for a host that provides the sheet itself —
   * the cover spread panels. No hidden measurement pass runs in `content` mode.
   */
  renderMode?: 'sheet' | 'content';
  /** Cover spread placement, forwarded to the page component as `spread`. */
  spread?: SpreadInfo;
}

interface FlowMeasurementHostProps {
  pageKey: string;
  version?: string;
  readiness?: ReturnType<typeof paginationReadiness.createScope>;
  onMeasurement: (pageKey: string, measurement: StaticFlowMeasurement, owner?: string) => void;
  onRemoval?: (pageKey: string, flowId: string, owner: string) => void;
  children: (context: StaticFlowContextValue) => React.ReactNode;
}

/**
 * The hidden copy a flow page is measured in: offscreen, aria-hidden, at the real sheet size.
 *
 * A FlowArea removed while this copy stays mounted discards its plan. When the copy itself goes
 * (a filter moves measurement between the visible sheet and a measure-only host), the plans stay
 * until the next host measures: deleting them would collapse the page count, which moves the host
 * back, and so on forever. Its layout cleanup runs before any FlowArea's passive cleanup, so the
 * areas see that the copy is going.
 */
function FlowMeasurementHost({ pageKey, version, readiness, onMeasurement, onRemoval, children }: FlowMeasurementHostProps) {
  const [host] = React.useState(() => ({ mounted: true }));
  const hostRef = React.useRef<HTMLDivElement>(null);

  useIsoLayoutEffect(() => {
    host.mounted = true;
    return () => { host.mounted = false; };
  }, [host]);

  // A hasFlow page that renders no FlowArea keeps pagination `measuring` (it may still be
  // loading). Mark the copy so a renderer that times out can report why.
  useIsoLayoutEffect(() => {
    const element = hostRef.current;
    if (!element || element.querySelector('[data-uhuu-flow-area]')) {
      element?.removeAttribute('data-uhuu-flow-error');
      return undefined;
    }
    element.setAttribute('data-uhuu-flow-error', 'missing-flow-region');
    if (!isDev() || warnedMissingRegions.has(pageKey)) return undefined;
    const timer = setTimeout(() => {
      if (!element.isConnected || element.querySelector('[data-uhuu-flow-area]')) return;
      warnedMissingRegions.add(pageKey);
      console.warn(
        `[uhuu-components] Page "${pageKey}" is marked hasFlow but renders no Static.FlowArea, so ` +
        'data-uhuu-pagination stays "measuring". Render a FlowArea with one Static.Flow in every branch ' +
        '(an empty Flow is one page), or remove hasFlow.'
      );
    }, MISSING_REGION_GRACE_MS);
    return () => clearTimeout(timer);
  });

  const registerMeasurement = React.useCallback(
    (measurement: StaticFlowMeasurement, owner?: string) => onMeasurement(pageKey, measurement, owner),
    [pageKey, onMeasurement]
  );
  const unregisterMeasurement = React.useCallback((flowId: string, owner: string) => {
    if (host.mounted) onRemoval?.(pageKey, flowId, owner);
  }, [host, pageKey, onRemoval]);

  const context = React.useMemo<StaticFlowContextValue>(() => ({
    mode: 'measure',
    pageIndex: 0,
    measurementVersion: version,
    pageKey,
    readiness,
    registerMeasurement,
    unregisterMeasurement,
  }), [version, pageKey, readiness, registerMeasurement, unregisterMeasurement]);

  return (
    <div
      ref={hostRef}
      style={{
        position: 'fixed',
        visibility: 'hidden',
        pointerEvents: 'none',
        left: '-100000px',
        top: 0,
        // FlowArea measures its own bounded page body. A 0×0 host makes
        // that body fall back to the total item height, which in turn
        // produces a one-page viewer/runtime chunk despite a correct
        // interactive Review measurement. Keep this offscreen surface at
        // the real Sheet dimensions while hiding it from the user.
        width: 'calc(var(--uhuu-page-width) + 2 * var(--uhuu-page-bleed))',
        height: 'calc(var(--uhuu-page-height) + 2 * var(--uhuu-page-bleed))',
        minWidth: 'calc(var(--uhuu-page-width) + 2 * var(--uhuu-page-bleed))',
        minHeight: 'calc(var(--uhuu-page-height) + 2 * var(--uhuu-page-bleed))',
        overflow: 'hidden',
        zIndex: -1,
      }}
      aria-hidden="true"
      data-uhuu-flow-measurement="true"
    >
      {children(context)}
    </div>
  );
}

/**
 * Small helper that renders a single page with Pagination + Sheet
 * and optional reference/overlay. Keeps templates from duplicating
 * the same scaffold for every page render.
 */
export function PageCanvas({
  pageId,
  templateId,
  componentKey,
  component: PageComponent,
  payload,
  pagePayload,
  integration,
  page,
  parentGroup,
  setup,
  reference,
  overlay,
  className,
  pageNo = 0,
  totalPages,
  measurementPageNo,
  measurementTotalPages,
  dataBinding,
  flowPageIndex = 0,
  flowChunksByFlowId,
  measureFlow = false,
  flowMeasurementKey,
  flowMeasurementVersion,
  flowReadiness,
  onFlowMeasurement,
  onFlowRemoval,
  renderVisible = true,
  renderMode = 'sheet',
  spread,
}: PageCanvasProps) {
  const renderOverlay = typeof overlay === 'function'
    ? (pageNo: number) => overlay({ pageNo, pageId })
    : () => overlay;

  // Build automatic class for page key targeting
  const pageKey = componentKey || templateId || pageId;
  const pageKeyClass = pageKey ? `uhuu-page--${pageKey}` : '';
  const combinedClassName = [pageKeyClass, className].filter(Boolean).join(' ');

  const renderComponent = (
    componentPageNo: number = pageNo,
    componentTotalPages: number | undefined = totalPages
  ) => PageComponent ? (
    <PageComponent
      payload={payload}
      pagePayload={pagePayload}
      integration={integration}
      pageId={pageId}
      templateId={templateId ?? componentKey ?? pageId}
      pageNum={componentPageNo}
      totalPages={componentTotalPages}
      page={page}
      parentGroup={parentGroup as PageGroup}
      componentKey={componentKey}
      dataBinding={dataBinding}
      spread={spread}
    />
  ) : null;

  const visibleFlowContext = React.useMemo(
    () => ({
      mode: 'visible' as const,
      pageIndex: flowPageIndex,
      chunksByFlowId: flowChunksByFlowId,
    }),
    [flowPageIndex, flowChunksByFlowId]
  );

  if (renderMode === 'content') {
    return (
      <>
        {reference}
        <StaticFlowContext.Provider value={visibleFlowContext}>
          {renderComponent(pageNo, totalPages)}
        </StaticFlowContext.Provider>
      </>
    );
  }

  return (
    <>
      {measureFlow && onFlowMeasurement && flowMeasurementKey && (
        <FlowMeasurementHost
          pageKey={flowMeasurementKey}
          version={flowMeasurementVersion}
          readiness={flowReadiness}
          onMeasurement={onFlowMeasurement}
          onRemoval={onFlowRemoval}
        >
          {(measureFlowContext) => (
            <Pagination setup={setup}>
              <Sheet className={combinedClassName} pageNo={pageNo} data-page-key={pageKey}>
                <StaticFlowContext.Provider value={measureFlowContext}>
                  {renderComponent(
                    measurementPageNo ?? pageNo,
                    measurementTotalPages ?? totalPages
                  )}
                </StaticFlowContext.Provider>
              </Sheet>
            </Pagination>
          )}
        </FlowMeasurementHost>
      )}

      {renderVisible && (
        <Pagination setup={setup}>
          <Sheet
            className={combinedClassName}
            pageNo={pageNo}
            overlay={({ pageNo }) => renderOverlay(pageNo)}
            data-page-key={pageKey}
          >
            {reference}
            <StaticFlowContext.Provider value={visibleFlowContext}>
              {renderComponent(pageNo, totalPages)}
            </StaticFlowContext.Provider>
          </Sheet>
        </Pagination>
      )}
    </>
  );
}

export default PageCanvas;
